// Agent Explorer -- the 27 letters of the alphabet, each read from its spec.
//
// Layer four of the ladder: Specs → Skills → Crons → Agents → Tools → Functions. An agent is a
// letter of docs/agents/AGENTS_ALPHABET.md bound by SOUL.md and AGENTS.md;
// its card is generated by scripts/agents-from-specs.mjs from
// specs/agents/<letter>.t27 through the real compiler, joined to the
// experience snapshot (public/agents/experience.json) by LETTER. Nothing on
// this page is typed twice: the skills an agent holds, the jobs that launch
// them, the counts in the ladder and the episodes it is credited with all come
// from the generated catalog, and an agent with no attributed episode says so.

import { useCallback, useEffect, useMemo, useState } from 'react'
import { useI18n } from '../i18n/context'
import { usePageMeta } from '../hooks/usePageMeta'
import { useHashParams } from '../hooks/useHashParams'
import { useDocumentLock, useViewport } from '../lib/useViewport'
import { HEADER_CHROME_MAX } from '../lib/viewport.generated'
import { ExplorerHeader } from '../components/ExplorerHeader'
import { ExplorerLibrary, type ExplorerItem } from '../components/ExplorerLibrary'
import { AgentSpecPanel } from '../components/AgentSpecPanel'
import { LayerLadder, type LadderStep } from '../components/LayerLadder'
import { loadAgentSpecs, type AgentLayer, type AgentSpecCatalog, type AgentSpecEntry } from '../lib/agentSpecs'
import { skillExplorerHash } from '../lib/skillsCatalog'
import { cronExplorerHash } from '../lib/cronsCatalog'
import { agentExplorerHash, canonicalAgentUrl, resolveAgent } from '../lib/agentsCatalog'
import { toolExplorerHash } from '../lib/toolsCatalog'
import { C, panelBox, pill, tagChip } from '../lib/explorerTheme'

