type Ui = Record<keyof typeof UI.en, string>

const TAG_FAMILIES = [
  { prefix: 'layer/', label: 'layer' },
  { prefix: 'witness/', label: 'witness' },
  { prefix: 'skills/', label: 'skills' },
  { prefix: 'ar/', label: 'AR' },
  { prefix: 'enabled/', label: 'enabled' },
]

const LAYER_LABEL: Record<AgentLayer, { en: string; ru: string }> = {
  Archetypal: { en: 'Archetypal', ru: 'Архетипический' },
  Spiritual: { en: 'Spiritual', ru: 'Духовный' },
  Physical: { en: 'Physical', ru: 'Физический' },
}

function tagsOf(a: AgentSpecEntry): string[] {
  return [
    `layer/${a.fields.LAYER.toLowerCase()}`,
    `witness/${a.witness}`,
    `skills/${a.skills.length > 0 ? 'bound' : 'none'}`,
    `ar/${a.fields.AR_ROLE ? 'yes' : 'no'}`,
    `enabled/${a.fields.ENABLED ? 'true' : 'false'}`,
  ]
}

function shortDate(iso: string | null): string {
  return iso ? iso.replace('T', ' ').slice(0, 16) : '—'
}

export default function AgentExplorer() {
  const { lang } = useI18n()
  const ui: Ui = lang === 'ru' ? UI.ru : UI.en
  const short = lang === 'ru' ? 'ru' : 'en'
  usePageMeta(ui.metaTitle, ui.metaDescription)
  const params = useHashParams()
  const embedded = params.embedded

  const [catalog, setCatalog] = useState<AgentSpecCatalog | null>(null)
  const [selected, setSelected] = useState<AgentSpecEntry | null>(null)
  const [err, setErr] = useState<string | null>(null)
  const [query, setQuery] = useState('')
  const [layer, setLayer] = useState('')
  const [witnessFilter, setWitnessFilter] = useState<'all' | 'spec+experience' | 'spec-only'>('all')
  const [tagSel, setTagSel] = useState<string[]>([])
  const [copied, setCopied] = useState(false)
  // Layout tier from specs/ui/viewport.t27 (via useViewport); `narrow` trims the
  // header chrome and is not a tier. Phone and tablet lock the document: the
  // panes are the scrollers there.
  const viewport = useViewport()
  const phone = viewport.tier === 'phone'
  const compact = phone || viewport.tier === 'tablet'
  const narrow = viewport.width < HEADER_CHROME_MAX
  useDocumentLock(compact)
  const [pane, setPane] = useState<'list' | 'detail'>('list')

  const pick = useCallback(
    (entry: AgentSpecEntry) => {
      setSelected(entry)
      params.set(agentExplorerHash(entry.letter, { embedded }))
    },
    [embedded, params],
  )

  useEffect(() => {
    let alive = true
    loadAgentSpecs()
      .then((c) => {
        if (!alive) return
        setCatalog(c)
        const wanted = params.get('agent')
        try {
          const target = resolveAgent(c, wanted)
          if (wanted) setPane('detail')
          pick(target)
        } catch (e) {
          setErr(String(e instanceof Error ? e.message : e))
          setPane('detail')
        }
      })
      .catch((e) => {
        if (!alive) return
        setErr(String(e instanceof Error ? e.message : e))
        setPane('detail')
      })
    return () => {
      alive = false
    }
    // Mount only: the deep link is read once.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  // A deep link that arrives after mount (the back button, a link on this
  // page, a script setting the hash): open that card, on a phone as the card
  // pane. Measured before this at 390x844: `#/agents` then a `?agent=` hash
  // kept the list, because the parameters were read once.
  useEffect(() => {
    if (!catalog || params.changes === 0) return
    const wanted = params.get('agent')
    if (!wanted) return
    try {
      const target = resolveAgent(catalog, wanted)
      setPane('detail')
      if (target !== selected) pick(target)
    } catch {
      // An unknown id in a later hash: keep the card that is open.
    }
    // Only the hash counter: the catalog and the selection are read, not followed.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [params.changes])

  const agents = useMemo(() => catalog?.agents ?? [], [catalog])

  const filtered = useMemo(() => {
    const q = query.trim().toLowerCase()
    return agents.filter((a) => {
      if (layer && a.fields.LAYER !== layer) return false
      if (witnessFilter !== 'all' && a.witness !== witnessFilter) return false
      if (tagSel.length) {
        const tags = tagsOf(a)
        if (!tagSel.every((t) => tags.includes(t))) return false
      }
      if (!q) return true
      const f = a.fields
      return (
        a.letter.toLowerCase() === q ||
        a.id.toLowerCase().includes(q) ||
        `${f.LETTER_NAME} ${f.NAME} ${f.DOMAIN} ${f.ARCHETYPE} ${f.REGISTER} ${f.AR_ROLE}`.toLowerCase().includes(q) ||
        Object.values(a.summary).join(' ').toLowerCase().includes(q) ||
        Object.values(a.name).join(' ').toLowerCase().includes(q) ||
        a.skills.some((s) => s.id.toLowerCase().includes(q))
      )
    })
  }, [agents, query, layer, witnessFilter, tagSel])

  const tagCounts = useMemo(() => {
    const acc: Record<string, number> = {}
    for (const a of filtered) for (const t of tagsOf(a)) acc[t] = (acc[t] ?? 0) + 1
    return acc
  }, [filtered])

  const items: ExplorerItem[] = useMemo(
    () =>
      filtered.map((a) => ({
        id: a.id,
        // The letter leads, as in the alphabet table; the name follows in the reader's locale.
        title: `${a.letter} · ${a.name[short] ?? a.name.en}`,
        subtitle: a.fields.DOMAIN,
        badge: a.skills.length > 0 ? `◷ ${a.skills.length}` : a.fields.ENABLED ? undefined : ui.enabledOff,
        badgeColor: a.skills.some((s) => !s.ok) ? C.bad : undefined,
        health: a.health,
        tags: tagsOf(a),
        haystack: `${a.letter} ${a.id} ${a.fields.LETTER_NAME} ${a.fields.DOMAIN}`.toLowerCase(),
      })),
    [filtered, short, ui.enabledOff],
  )

  const copy = useCallback(() => {
    if (!selected) return
    navigator.clipboard?.writeText(canonicalAgentUrl(selected.letter)).then(
      () => {
        setCopied(true)
        window.setTimeout(() => setCopied(false), 1400)
      },
      () => {},
    )
  }, [selected])

  const box = panelBox(embedded)
  const showList = !phone || pane === 'list'
  const showDetail = !phone || pane === 'detail'
  const counts = catalog?.counts
  const withExp = counts?.specPlusExperience ?? 0
  const specOnly = counts?.specOnly ?? 0

  const ladderSteps: LadderStep[] = useMemo(() => {
    const l = catalog?.ladder
    const embed = embedded ? '?embed=1' : ''
    return [
      { key: 'specs', label: ui.ladderSpecs, count: l?.specs ?? null, href: `#/specs${embed}` },
      { key: 'skills', label: ui.ladderSkills, count: l?.skills ?? null, href: `#/skills${embed}` },
      { key: 'crons', label: ui.ladderCrons, count: l?.crons ?? null, href: `#/crons${embed}` },
      { key: 'agents', label: ui.ladderAgents, count: l?.agents ?? null, href: `#/agents${embed}`, current: true },
      { key: 'tools', label: ui.ladderTools, count: l?.tools ?? null, href: `#/tools${embed}` },
      { key: 'functions', label: ui.ladderFunctions, count: l?.functions ?? null, href: `#/functions${embed}` },
      { key: 'providers', label: ui.ladderProviders, count: l?.providers ?? null, href: `#/providers${embed}` },
    ]
  }, [catalog, embedded, ui.ladderSpecs, ui.ladderSkills, ui.ladderCrons, ui.ladderAgents, ui.ladderTools, ui.ladderFunctions, ui.ladderProviders])

  const heading = (text: string) => <div style={{ fontSize: 11, color: C.muted, fontFamily: C.mono }}>{text}</div>
  const row = (label: string, value: React.ReactNode) => (
    <div style={{ display: 'flex', gap: 10, alignItems: 'baseline', flexWrap: 'wrap' }}>
      <span style={{ fontSize: 10.5, color: C.muted, fontFamily: C.mono, minWidth: 92 }}>{label}</span>
      <span style={{ fontSize: 12.5, color: '#d8d8d8', minWidth: 0, wordBreak: 'break-word' }}>{value}</span>
    </div>
  )
  const live = (text: string) => <span data-lang-exempt="live">{text}</span>

  const chipLink = (href: string, text: string, glyph: string, ok = true) =>
    ok ? (
      <a className="spec-x-target" key={text} href={href} style={{ ...tagChip(false, false), color: C.accent, borderColor: C.borderBright, textDecoration: 'none' }} data-lang-exempt="live">
        {glyph} {text}
      </a>
    ) : (
      <span key={text} style={{ ...tagChip(false, false), color: C.bad, borderColor: C.bad }} data-lang-exempt="live">
        ✕ {text}
      </span>
    )

  const snapshot = catalog?.experienceSnapshot ?? null

  return (
    <div
      className="spec-x"
      data-tier={viewport.tier}
      data-embedded={embedded ? '1' : undefined}
      style={{
        height: '100dvh',
        display: 'flex',
        flexDirection: 'column',
        background: C.bg,
        color: C.text,
        fontFamily: "'Outfit', system-ui, sans-serif",
        overflow: 'hidden',
      }}
    >
      {!embedded && (
        <ExplorerHeader
          title={ui.title}
          subtitle={ui.subtitle}
          back={ui.back}
          note={ui.note}
          provenance={
            snapshot
              ? snapshot.sources.map((s) => ({ repo: s.repo === 't27' ? 'gHashTag/t27' : 'gHashTag/trinity', shortCommit: s.commit.slice(0, 7) }))
              : undefined
          }
          provenanceLabel={ui.snapshotFrom}
          narrow={narrow}
          phone={phone}
        />
      )}
      {/* One ladder per screen -- see components/LayerLadder. */}
      {!embedded && <LayerLadder steps={ladderSteps} caption={ui.ladder} />}

      <div style={{ flex: 1, display: 'flex', minHeight: 0, minWidth: 0 }}>
        {showList && (
          <ExplorerLibrary
            items={items}
            selectedId={selected?.id ?? null}
            onPick={(item) => {
              const entry = agents.find((a) => a.id === item.id)
              if (entry) {
                setPane('detail')
                pick(entry)
              }
            }}
            query={query}
            setQuery={setQuery}
            categories={(Object.entries(counts?.byLayer ?? {}) as [AgentLayer, number][]).map(
              ([k, n]) => [k, LAYER_LABEL[k]?.[short] ?? k, n] as [string, string, number],
            )}
            category={layer}
            setCategory={setLayer}
            filters={[
              { key: 'all', label: ui.filterAll, count: agents.length },
              { key: 'spec+experience', label: ui.filterWithExperience, count: withExp, color: C.accent, glyph: '✓' },
              { key: 'spec-only', label: ui.filterSpecOnly, count: specOnly, color: C.warn, glyph: '○' },
            ]}
            filter={witnessFilter}
            setFilter={(v) => setWitnessFilter(v as 'all' | 'spec+experience' | 'spec-only')}
            stack={[
              { key: 'spec+experience', count: withExp, color: C.accent, label: ui.filterWithExperience },
              { key: 'spec-only', count: specOnly, color: C.warn, label: ui.filterSpecOnly },
            ]}
            tagCounts={tagCounts}
            tagFamilies={TAG_FAMILIES}
            tagSel={tagSel}
            toggleTag={(t) => setTagSel((prev) => (prev.includes(t) ? prev.filter((x) => x !== t) : [...prev, t]))}
            clearTags={() => setTagSel([])}
            tier={viewport.tier}
            countLabel={`${filtered.length} ${ui.agents}`}
            titlesAreGenerated
            ui={{
              search: ui.search,
              allCategories: `${ui.allLayers} (${agents.length})`,
              tags: ui.tags,
              clear: ui.clear,
              noResults: ui.noResults,
              noneInGroup: ui.noneInGroup,
              filters: ui.filters,
            }}
          />
        )}

        {showDetail && (
          <main style={{ flex: 1, display: 'flex', flexDirection: 'column', minWidth: 0, minHeight: 0, overflowY: 'auto' }}>
            {err && (
              <div
                className="spec-x-banner"
                style={{
                  margin: '10px 14px 0',
                  padding: '9px 12px',
                  background: 'rgba(248,81,73,0.10)',
                  border: `1px solid ${C.bad}`,
                  borderRadius: 5,
                  fontSize: 12,
                  color: '#d8d8d8',
                }}
              >
                <span style={{ color: C.bad, fontWeight: 700 }}>⚠ {ui.failed}</span> <span data-lang-exempt="live">{err}</span>
              </div>
            )}
            {!selected && !err && <div style={{ padding: 24, color: C.muted, fontSize: 13 }}>{catalog ? ui.pickAgent : ui.loading}</div>}
            {selected && (
              <div data-card={selected.id} style={{ padding: 14, display: 'flex', flexDirection: 'column', gap: 12 }}>
                {phone && (
                  <button onClick={() => setPane('list')} className="spec-x-back" style={{ ...pill, alignSelf: 'flex-start' }}>
                    ← {ui.backToLibrary}
                  </button>
                )}
                <div style={{ display: 'flex', alignItems: 'baseline', gap: 10, flexWrap: 'wrap' }}>
                  <span
                    aria-hidden="true"
                    style={{
                      fontFamily: C.mono,
                      fontSize: 28,
                      fontWeight: 700,
                      lineHeight: 1,
                      color: C.golden,
                      minWidth: 36,
                      textAlign: 'center',
                      border: `1px solid ${C.borderBright}`,
                      borderRadius: 6,
                      padding: '4px 6px',
                    }}
                  >
                    {selected.letter}
                  </span>
                  <span style={{ fontSize: 15, fontWeight: 700 }} data-lang-exempt="live">
                    {selected.name[short] ?? selected.name.en}
                  </span>
                  <span style={{ fontFamily: C.mono, fontSize: 11, color: C.muted }} data-lang-exempt="live">
                    {selected.id} · {ui.ordinal} {selected.ordinal}
                  </span>
                  <span style={{ ...tagChip(false, false), cursor: 'default' }} data-lang-exempt="live">
                    {LAYER_LABEL[selected.fields.LAYER]?.[short] ?? selected.fields.LAYER}
                  </span>
                  <button onClick={copy} style={{ ...pill, color: copied ? C.accent : C.muted, marginLeft: 'auto' }}>
                    {copied ? ui.copied : ui.copyLink}
                  </button>
                </div>

                {/* The spec comes first: it is the statement about the letter;
                    the boxes below are what the catalogs and the snapshot saw. */}
                <AgentSpecPanel
                  lang={short}
                  kind="agent"
                  id={selected.id}
                  entry={selected}
                  embedded={embedded}
                  flat={compact}
                  i18n={catalog?.i18n ?? []}
                  links={selected.skills.map((s) => ({ id: s.id, ok: s.ok, href: s.ok ? skillExplorerHash(s.id, { embedded }) : '#' }))}
                  extraControls={
                    <>
                      <a className="spec-x-target" href={selected.links.soul} target="_blank" rel="noopener noreferrer" style={pill}>
                        {ui.openSoul}
                      </a>
                      <a className="spec-x-target" href={selected.links.agentsDoc} target="_blank" rel="noopener noreferrer" style={pill}>
                        {ui.openAgentsDoc}
                      </a>
                      {selected.links.experienceLog && (
                        <a className="spec-x-target" href={selected.links.experienceLog} target="_blank" rel="noopener noreferrer" style={pill}>
                          {ui.experienceLog}
                        </a>
                      )}
                    </>
                  }
                />

                {/* ---- soul & law ---- */}
                <div style={{ ...box, padding: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {heading(ui.soulLaw)}
                  <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.5 }}>{ui.soulLawHint}</div>
                  <div style={{ display: 'flex', gap: 5, flexWrap: 'wrap' }}>
                    <a className="spec-x-target" href={selected.links.soul} target="_blank" rel="noopener noreferrer" style={pill} data-lang-exempt="live">
                      {selected.fields.SOUL}
                    </a>
                    <a className="spec-x-target" href={selected.links.agentsDoc} target="_blank" rel="noopener noreferrer" style={pill} data-lang-exempt="live">
                      {selected.fields.AGENTS_DOC}
                    </a>
                    <a className="spec-x-target" href={selected.links.alphabet} target="_blank" rel="noopener noreferrer" style={pill} data-lang-exempt="live">
                      {selected.fields.ALPHABET}
                    </a>
                  </div>
                  <div style={{ fontFamily: C.mono, fontSize: 10.5, color: C.muted }}>
                    {ui.pinnedAt} <span data-lang-exempt="live">{selected.links.pinnedAt.slice(0, 12)}</span>{' '}
                    <span style={{ opacity: 0.7 }} data-lang-exempt="live">
                      ({selected.links.pinSource})
                    </span>
                  </div>
                </div>

                {/* ---- crons (derived) ---- */}
                <div style={{ ...box, padding: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {heading(ui.crons)}
                  <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.5 }}>{ui.cronsHint}</div>
                  {selected.crons.length === 0 ? (
                    <div style={{ fontSize: 12, color: C.muted }}>{selected.skills.length === 0 ? ui.noCronsNoSkills : ui.noCrons}</div>
                  ) : (
                    <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                      {selected.crons.map((id) => chipLink(cronExplorerHash(id, { embedded }), id, '⟲'))}
                    </div>
                  )}
                </div>

                {/* ---- experience ---- */}
                <div style={{ ...box, padding: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
                  <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, flexWrap: 'wrap' }}>
                    {heading(ui.experience)}
                    <span style={{ fontFamily: C.mono, fontSize: 11.5, color: selected.experience.episodes > 0 ? C.accent : C.muted }}>
                      <b data-lang-exempt="live">{selected.experience.episodes}</b> {ui.episodes}
                    </span>
                  </div>
                  {selected.experience.episodes === 0 ? (
                    <>
                      <div style={{ fontSize: 12, color: C.warn }}>{ui.noEpisodes}</div>
                      <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.5 }}>{ui.noEpisodesHint}</div>
                    </>
                  ) : (
                    <>
                      {row(ui.firstEpisode, live(shortDate(selected.experience.first)))}
                      {row(ui.lastEpisode, live(shortDate(selected.experience.last)))}
                      {selected.experience.lastTask && row(ui.lastTask, live(selected.experience.lastTask))}
                      {row(
                        ui.outcomes,
                        live(
                          Object.entries(selected.experience.outcomes)
                            .map(([k, n]) => `${k} ${n}`)
                            .join(' · ') || '—',
                        ),
                      )}
                      {selected.experience.lessons.length > 0 && (
                        <div>
                          <div style={{ fontSize: 10.5, color: C.muted, fontFamily: C.mono, marginBottom: 4 }}>{ui.lessons}</div>
                          <ul style={{ margin: 0, paddingLeft: 18, fontSize: 12, lineHeight: 1.5, color: '#d8d8d8' }} data-lang-exempt="live">
                            {selected.experience.lessons.map((l, i) => (
                              <li key={i}>{l}</li>
                            ))}
                          </ul>
                        </div>
                      )}
                    </>
                  )}
                  {snapshot?.counts && (
                    <div style={{ fontFamily: C.mono, fontSize: 10.5, color: C.muted }}>
                      {ui.unattributed}: <span data-lang-exempt="live">{snapshot.counts.unattributed}</span> · {ui.snapshotFrom}{' '}
                      <span data-lang-exempt="live">
                        {snapshot.sources.map((s) => `${s.repo}@${s.commit.slice(0, 7)} (${s.episodes})`).join(', ')}
                      </span>
                    </div>
                  )}
                </div>

                {/* ---- invariants ---- */}
                <div style={{ ...box, padding: 12, display: 'flex', flexDirection: 'column', gap: 6 }}>
                  {heading(ui.invariants)}
                  {row(ui.entry, live(selected.fields.ENTRY_INVARIANT))}
                  {row(ui.exit, live(selected.fields.EXIT_INVARIANT))}
                  {row(ui.archetype, live(selected.fields.ARCHETYPE))}
                  {row(ui.register, live(selected.fields.REGISTER))}
                  {row(ui.layer, live(LAYER_LABEL[selected.fields.LAYER]?.[short] ?? selected.fields.LAYER))}
                  {row(ui.clara, selected.fields.AR_ROLE ? live(selected.fields.AR_ROLE) : ui.noClara)}
                  {row(
                    ui.keyFiles,
                    selected.fields.KEY_FILES.length === 0 ? (
                      ui.noKeyFiles
                    ) : (
                      <span style={{ fontFamily: C.mono, fontSize: 11.5 }} data-lang-exempt="live">
                        {selected.fields.KEY_FILES.join(' · ')}
                      </span>
                    ),
                  )}
                </div>

                {/* ---- tools (layer five) ---- */}
                <div style={{ ...box, padding: 12, display: 'flex', flexDirection: 'column', gap: 8 }}>
                  {heading(ui.tools)}
                  <div style={{ fontSize: 11.5, color: C.muted, lineHeight: 1.5 }}>{ui.toolsHint}</div>
                  {selected.tools.length === 0 ? (
                    <div style={{ fontSize: 12, color: C.muted }}>
                      {ui.noTools}
                      {selected.fields.TOOLS_NOTE ? <span data-lang-exempt="live"> — {selected.fields.TOOLS_NOTE}</span> : null}
                    </div>
                  ) : (
                    <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                      {selected.tools.map((t) => chipLink(t.ok ? toolExplorerHash(t.id, { embedded }) : '#', t.id, '⚙', t.ok))}
                    </div>
                  )}
                </div>
              </div>
            )}
          </main>
        )}
      </div>
    </div>
  )
}
